def page_help(request):
    name=getattr(getattr(request,'resolver_match',None),'url_name','') or ''
    help_topic=TOPICS.get('notice_new' if name=='notice_edit' else name)
    if name in ['task_action','official_action']:
        action=request.resolver_match.kwargs.get('action') or request.resolver_match.kwargs.get('kind')
        labels={'progress':'진행 보고','submit':'완료 보고','review':'완료 검토','feedback':'피드백','approve':'결재 승인','return':'보완 요청','recall':'보고 회수'}
        help_topic=topic(labels.get(action,'업무 처리'),'선택한 업무에 보고·승인·피드백을 남기는 화면입니다.',
            ['화면 제목과 대상 업무를 확인합니다.','현재 진행률·결과물·검토 사유 등 표시된 항목을 작성합니다.','저장하면 업무 상태나 이력에 반영됩니다.'],['진행 보고는 현재 상황을 공유하는 것이며 완료 승인이 아닙니다.','완료 보고 후에는 지정된 결재 절차에 따라 최종 완료됩니다. 반려되면 내용을 보완해 다시 보고합니다.'])
    elif name.startswith('intake_') and not help_topic:help_topic=TOPICS['intake_list']
    elif name=='personal_promote':help_topic=topic('개인 카드의 업무 전환','공유할 내용을 검토한 뒤 업무 초안을 만듭니다.',['개인 메모에서 공개할 내용만 남깁니다.','담당자와 결재라인을 정하고 업무를 저장합니다.'],['개인 카드의 전체 내용이 자동 공개되는 것은 아닙니다. 저장 전 공유 범위를 확인하세요.'])
    elif name in ['login','activate','mfa_setup','mfa_verify','mfa_restore','mfa_recovery','password_reset','password_reset_done','password_reset_confirm']:
        titles={'login':'로그인','activate':'회사 이메일 인증 · 계정 활성화','mfa_setup':'OTP 등록','mfa_verify':'OTP 인증','mfa_restore':'OTP 재등록','mfa_recovery':'인증 복구','password_reset':'비밀번호 재설정','password_reset_done':'비밀번호 재설정 메일 안내','password_reset_confirm':'새 비밀번호 설정'}
        help_topic=topic(titles[name],'회사 이메일과 본인 인증으로 Workhub에 안전하게 접근합니다.',
            ['화면 안내에 따라 회사 이메일·비밀번호 또는 인증 코드를 입력합니다.','초대받은 직원은 이메일 인증·비밀번호 설정·OTP 등록을 순서대로 완료합니다.'],
            ['OTP 코드는 휴대폰 인증 앱에 표시되는 일회용 코드입니다. 이메일 인증 코드와 다릅니다.','휴대폰을 분실했거나 OTP를 사용할 수 없으면 관리자에게 본인 확인 후 재등록을 요청하세요.','비밀번호 재설정은 기존 OTP를 없애지 않습니다. 비밀번호와 인증 코드는 다른 사람에게 공유하지 마세요.'])
